package com.example.starter.tailings.domain;

/**
 * 调洪演算判定结论。severity 用于库容口径与安全口径取最重：
 * SAFE 安全 &lt; CRITICAL 临界 &lt; MUST_DISCHARGE 须泄流 &lt; DANGER 险。
 */
public enum Verdict {

    SAFE(0),
    CRITICAL(1),
    MUST_DISCHARGE(2),
    DANGER(3);

    private final int severity;

    Verdict(int severity) {
        this.severity = severity;
    }

    public int severity() {
        return severity;
    }

    /**
     * 取两个口径中更重的判定。
     */
    public static Verdict worst(Verdict a, Verdict b) {
        return a.severity >= b.severity ? a : b;
    }
}

package com.example.starter.tailings.domain;

/**
 * 泄流指令状态：下达 → 签收 → 执行 → 回执；签收超时进入已升级。
 */
public enum CommandStatus {

    ISSUED,
    ACKED,
    EXECUTING,
    RECEIPTED,
    ESCALATED
}

package com.example.starter.tailings.domain;

/**
 * 泄流方案状态：EFFECTIVE 生效中，COMPLETED 已完结（复盘归档后）。
 */
public enum PlanStatus {

    EFFECTIVE,
    COMPLETED
}

package com.example.starter.tailings.domain;

/**
 * 监测读数类型：RAINFALL 降雨(毫米)、WATER_LEVEL 水位(米)、
 * DRY_BEACH 干滩长度(米)、PHREATIC_LINE 浸润线埋深(米)。
 */
public enum ReadingType {

    RAINFALL,
    WATER_LEVEL,
    DRY_BEACH,
    PHREATIC_LINE
}

package com.example.starter.tailings.error;

import org.springframework.http.HttpStatus;

/**
 * 业务异常，携带 HTTP 状态码，由全局异常处理器转换为统一错误响应。
 */
public class BusinessException extends RuntimeException {

    private final HttpStatus status;

    public BusinessException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static BusinessException badRequest(String message) {
        return new BusinessException(HttpStatus.BAD_REQUEST, message);
    }

    public static BusinessException notFound(String message) {
        return new BusinessException(HttpStatus.NOT_FOUND, message);
    }

    public static BusinessException conflict(String message) {
        return new BusinessException(HttpStatus.CONFLICT, message);
    }
}

package com.example.starter.tailings.error;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.stream.Collectors;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 统一错误响应：{"status": 状态码, "error": 错误说明}。
 */
@RestControllerAdvice
public class ApiExceptionHandler {

    @ExceptionHandler(BusinessException.class)
    public ResponseEntity<Map<String, Object>> handleBusiness(BusinessException ex) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("status", ex.status().value());
        body.put("error", ex.getMessage());
        return ResponseEntity.status(ex.status()).body(body);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .map(e -> e.getField() + " " + e.getDefaultMessage())
                .collect(Collectors.joining("; "));
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("status", 400);
        body.put("error", message);
        return ResponseEntity.badRequest().body(body);
    }
}

package com.example.starter.tailings.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间源配置：业务时间统一走 Clock，便于测试用可控时钟覆盖签收时限等时间口径。
 */
@Configuration
public class TimeConfig {

    @Bean
    public Clock clock() {
        return Clock.systemDefaultZone();
    }
}

