                                rs.getString("request_id"),
                                rs.getLong("pond_id"),
                                (Long) rs.getObject("calc_id"),
                                (Long) rs.getObject("plan_id"),
                                (Long) rs.getObject("command_id"),
                                rs.getString("status"),
                                rs.getObject("archived_at", LocalDateTime.class)),
                        pondId)
                .stream()
                .findFirst();
    }
}

