        long commandId;
        try {
            commandId = commandRepository.insert(requestId, planId, plan.pondId(),
                    CommandStatus.ISSUED.name(), issuedAt, deadline);
        } catch (DuplicateKeyException e) {
            throw BusinessException.conflict("该方案已下达过指令");
        }
