                        rs.getString("point_code"),
                        rs.getString("reading_type"),
                        rs.getObject("sample_time", LocalDateTime.class),
                        rs.getBigDecimal("reading_value"),
                        rs.getString("detail"),
                        rs.getObject("created_at", LocalDateTime.class)),
                pondId);
    }
}

