@Repository
public class CommandRepository {

    private final JdbcTemplate jdbc;

    public CommandRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 泄流指令行。时间字段为 NULL 表示该环节尚未发生。
     *
     * @param id               主键
     * @param requestId        幂等请求ID
